/**
 * Serve-time connection resolution for one mounted agent: once the host is
 * listening (port known), symbolic transports — peers and the Cursor
 * account bridge — resolve to concrete URLs and join the engine's
 * resolved-connection set. Local turns call both over loopback; cloud
 * turns use the serve `publicUrl` for peers and the account's native
 * connectors instead of the bridge. A single-agent serve with a peers URL
 * reaches its peers there from both runtimes.
 */
import { isHostOauthConnectionTransport } from "../types.js";
import { resolveCursorAccountConnections, } from "./cursor/account-mcp.js";
import { resolveHostedPeerConnections, resolvePeerConnections, } from "./peer-connections.js";
/** Fail fast before listen when static cloud config cannot honor `servers`. */
export function validateMountConnectionsConfig(args) {
    if (args.accountRefs === undefined || args.accountRefs.length === 0) {
        return;
    }
    const agent = args.project.agent;
    const cloudCapable = agent.runtime === "cloud" || agent.cloud !== undefined;
    if (!cloudCapable || args.publicUrl !== undefined || args.cloudToolsBridge === true) {
        return;
    }
    const label = args.slug === "" ? args.project.name : args.slug;
    const hostConnectionNames = new Set((args.project.agent.hostConnections ?? []).map((connection) => connection.name));
    const filteredRefs = args.accountRefs.filter((ref) => ref.servers !== undefined && !hostConnectionNames.has(ref.name));
    if (filteredRefs.length === 0) {
        return;
    }
    throw new Error(`[bdk] agent "${label}" has Cursor account MCP connections with \`servers\` filters (${filteredRefs
        .map((ref) => ref.name)
        .join(", ")}) but no --public-url; cloud-runtime turns cannot honor those filters without a public bridge URL. Set --public-url or remove the \`servers\` filter.`);
}
/** Fail closed when a cloud turn cannot honor a `servers` filter. */
export function assertCloudCanHonorAccountServersFilters(args) {
    if (args.runtime !== "cloud") {
        return;
    }
    const blocked = args.resolvedConnections.filter((connection) => connection.accountServersFilter !== undefined &&
        connection.cloudUrl === undefined &&
        args.bridgedNames?.has(connection.name) !== true);
    if (blocked.length === 0) {
        return;
    }
    throw new Error(`[bdk] cloud turn cannot honor Cursor account \`servers\` filters (${blocked
        .map((connection) => connection.name)
        .join(", ")}) without --public-url; set --public-url so cloud turns reach the filtered account bridge instead of falling back to native connectors.`);
}
/** Fail closed when anonymous HTTP admission would expose account connectors. */
export function assertAccountConnectionsNotAnonymous(args) {
    if (args.allowAnonymous !== true || !args.hasAccountConnections) {
        return;
    }
    if (args.allowAnonymousCursorAccountMcp === true) {
        return;
    }
    throw new Error("[bdk] --allow-anonymous cannot be used with Cursor account MCP connections (defineConnection({ cursorAccount: true })); use --bearer-token, or opt in with --allow-anonymous-cursor-account-mcp behind a trusted boundary.");
}
export function resolveMountConnections(args) {
    const agent = args.project.agent;
    const cloudCapable = agent.runtime === "cloud" || agent.cloud !== undefined;
    const label = args.slug === "" ? args.project.name : args.slug;
    const resolved = [];
    if (cloudCapable) {
        const hostOauthNames = agent.connections
            .filter((connection) => isHostOauthConnectionTransport(connection.transport))
            .map((connection) => connection.name);
        if (hostOauthNames.length > 0) {
            args.logger(args.cloudToolsBridge === true
                ? `[bdk] agent "${label}": host-OAuth MCP connections (${hostOauthNames.join(", ")}) reach cloud turns through the host connection bridge; their tokens stay on this serve host.`
                : `[bdk] warning: agent "${label}" has host-OAuth MCP connections (${hostOauthNames.join(", ")}) whose tokens live on this serve host; cloud-runtime turns omit them. Serve with a cloud tools URL so they reach turns through the host connection bridge, or drop \`oauth\` and authorize the server another way.`);
        }
    }
    const peerRefs = args.peerRefs ?? [];
    if (args.peersUrl !== undefined) {
        resolved.push(...resolveHostedPeerConnections({ refs: peerRefs, peersUrl: args.peersUrl }));
    }
    else if (peerRefs.length > 0) {
        const peers = resolvePeerConnections({
            refs: peerRefs,
            serverUrl: args.serverUrl,
            ...(args.publicUrl === undefined ? {} : { publicUrl: args.publicUrl }),
            ...(args.authToken === undefined ? {} : { authToken: args.authToken }),
        });
        resolved.push(...peers);
        if (cloudCapable && args.publicUrl === undefined) {
            args.logger(`[bdk] warning: agent "${label}" has peer MCP connections (${peers
                .map((peer) => peer.name)
                .join(", ")}) but no --public-url; cloud-runtime turns cannot reach this host's loopback address, so peers are omitted from cloud turns.`);
        }
    }
    if (args.accountRefs !== undefined && args.accountBridge !== undefined) {
        resolved.push(...resolveCursorAccountConnections({
            refs: args.accountRefs,
            serverUrl: args.serverUrl,
            basePath: args.slug === "" ? "" : `/${args.slug}`,
            bridgeSecret: args.accountBridge.secret,
            ...(args.publicUrl === undefined ? {} : { publicUrl: args.publicUrl }),
        }));
        // Non-blocking startup DX: connector statuses land in the serve log.
        void args.accountBridge.logPreflight(args.accountRefs);
        if (cloudCapable && args.publicUrl === undefined) {
            args.logger(args.cloudToolsBridge === true
                ? `[bdk] agent "${label}": cloud-runtime turns reach filtered account connections through the host connection bridge (unfiltered ones fall back to the account's native connectors).`
                : `[bdk] agent "${label}": cloud-runtime turns omit the account bridge without --public-url (cloud agents fall back to the account's native connectors).`);
        }
    }
    return resolved;
}
